        }
        
        $this->removeAndFlush($partenaire);
    }
    
    public function addPartenaire($request)
    {
        
        $partenaire = new utilisateur();
        
        if(!empty($request->get('prenom')))
        {
            $partenaire->setPrenom($request->get('prenom'));
        }
        
        if(!empty($request->get('nom')))
        {
            $partenaire->setNom($request->get('nom'));
        }
        
        if(!empty($request->get('login')))
        {
            $partenaire->setLogin($request->get('login'));
        }
        
        if(!empty($request->get('password')))
        {
            $partenaire->setPassword($request->get('password'));
        }
        
        //Ajout de la Photo
        if(!empty($_FILES["photoTelechargement"]["name"]))
        {
            $partenaire->setPhoto($this->uploadFile("photoTelechargement"));
        }
        
        if(!empty($request->get('type')))
        {
            $partenaire->setType($request->get('type'));
        }
        
        if(!empty($request->get('telephone')))
        {
            $partenaire->setTelephone($request->get('telephone'));
        }
        
        if(!empty($request->get('email')))
        {
            $partenaire->setEmail($request->get('email'));
        }
        
        if(!empty($request->get('poste')))
        {
            $partenaire->setPoste($request->get('poste'));
        }
           
        if(!empty($request->get('descriptionDetaillee')))
        {
            $partenaire->setDescriptionDetaillee($request->get('descriptionDetaillee'));
        }
        

        //Ajout de l'Entreprise
        if(!empty($request->get('listeEntreprises')))
        {
            $entrepriseRepository = $this->getEntityManager()->getRepository(entreprise::class);
            $entreprise = $entrepriseRepository->findOneBy(array('id' => $request->get('listeEntreprises')));
            $partenaire->setEntreprise($entreprise);
        }
        
        //Ajout des technologies (une ou plusieurs)
        if(!empty($_POST['listeTechnologies']))
        {
            //Parcours et Ajout des technologies
            foreach ($_POST['listeTechnologies'] as $Technologie)
            {
                $technologieRepository = $this->getEntityManager()->getRepository(technologie::class);
                $technologie = $technologieRepository->findOneBy(array('id' => $Technologie));
                
                if(empty($technologie))
                {
                    $technologie = new technologie();
                    $technologie->setNom($technologie);
                    $this->persistAndFlush($technologie);
                }
                $partenaire->addTechnologie($technologie);
            }
            $this->persistAndFlush($partenaire);
        }

        $this->persistAndFlush($partenaire);
    }

    public function updatePartenaire($request)
    {
        
        $partenaire = $this->findOneBy(array('id' => $request->get('id')));
        
        if(!empty($request->get('prenom')))
        {
            $partenaire->setPrenom($request->get('prenom'));
        }
        
        if(!empty($request->get('nom')))
        {
            $partenaire->setNom($request->get('nom'));
        }
        
        if(!empty($request->get('login')))
        {
            $partenaire->setLogin($request->get('login'));
        }
        
        if(!empty($request->get('password')))
        {
            $partenaire->setPassword($request->get('password'));
        }
        
        //Ajout de la Photo
        if(!empty($_FILES["photoTelechargement"]["name"]))
        {
            unlink($partenaire->getPhoto());
            
            $partenaire->setPhoto($this->uploadFile("photoTelechargement"));
        }
        
        if(!empty($request->get('type')))
        {
            $partenaire->setType($request->get('type'));
        }
        
        if(!empty($request->get('telephone')))
        {
            $partenaire->setTelephone($request->get('telephone'));
        }
        
        if(!empty($request->get('email')))
        {
            $partenaire->setEmail($request->get('email'));
        }
        
        if(!empty($request->get('poste')))
        {
            $partenaire->setPoste($request->get('poste'));
        }
        
        if(!empty($request->get('descriptionDetaillee')))
        {
            $partenaire->setDescriptionDetaillee($request->get('descriptionDetaillee'));
        }
        
        
        //Ajout de l'Entreprise
        if(!empty($request->get('listeEntreprises')))
        {
            $entrepriseRepository = $this->getEntityManager()->getRepository(entreprise::class);
            $entreprise = $entrepriseRepository->findOneBy(array('id' => $request->get('listeEntreprises')));
            $partenaire->setEntreprise($entreprise);
        }
        
        //Ajout des technologies (une ou plusieurs)
        if(!empty($_POST['listeTechnologies']))
        {
            //Parcours et Ajout des technologies
            foreach ($_POST['listeTechnologies'] as $Technologie)
            {
                $technologieRepository = $this->getEntityManager()->getRepository(technologie::class);
                $technologie = $technologieRepository->findOneBy(array('id' => $Technologie));
                
                if (!$partenaire->getListeTechnologies()->contains($technologie))
                {
                    $partenaire->addTechnologie($technologie);
                }  
                
            }
            //$this->persistAndFlush($partenaire);
        }
        try
        {
            $this->persistAndFlush($partenaire);
        }catch(\Doctrine\DBAL\DBALException $e){throw $e;}
 
    }
    
    public function uploadFile($fileName)
    {
        try
        {
            
            $filename = $_FILES[$fileName]["name"];
            $file_basename = substr($filename, 0, strripos($filename, '.')); // get file extention
            $file_ext = substr($filename, strripos($filename, '.')); // get file name
            $filesize = $_FILES[$fileName]["size"];
            $allowed_file_types = array('.doc','.docx','.jpg','.jpeg','.gif','.png','.pdf');
            
            if (in_array($file_ext,$allowed_file_types) && ($filesize < 8388608 ))
            {
                // Rename file
                $newfilename = md5(uniqid()).$file_ext;
                if (file_exists("uploads/partenaires/" . $newfilename))
                {
                    // file already exists error
                    echo "You have already uploaded this file.";
                }
                else
                {
                    move_uploaded_file($_FILES[$fileName]["tmp_name"], "uploads/partenaires/".$newfilename);
                    echo "File uploaded successfully.";
                }
            }
            elseif (empty($file_basename))
            {
                // file selection error
                echo "Please select a file to upload.";
            }
            elseif ($filesize > 8388608 )
            {
                // file size error
                echo "The file you are trying to upload is too large.";
            }
            else
            {
                // file type error
                echo "Only these file typs are allowed for upload: " . implode(', ',$allowed_file_types);
                unlink($_FILES[$fileName]["tmp_name"]);
            }
            //retourne le nouveau nom du fichier dans le dossier /uploads
            return "uploads/partenaires/".$newfilename;
            
        }
        catch(\Doctrine\DBAL\DBALException $e){}
    }

