    public function removeTechnologieForPartenaire($idPartenaire,$idTechnologie)
    {
        $partenaire = $this->findOneBy(array('id' => $idPartenaire));
        
        $technologieRepository = $this->getEntityManager()->getRepository(technologie::class);
        $technologie = $technologieRepository->findOneBy(array('id' => $idTechnologie));
        
        $partenaire->removeTechnologie($technologie);
        
